contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: from is an address to act as sender (must be this contract since only this contract deployed c can be msg.sender for calls), to is recipient, amount is transfer amount
    function run(address to, uint256 amount) public payable {
        require(true);
        // Preconditions: this test contract is the owner/initial holder because checker deploys fresh C with msg.sender = this contract.
        // Read before-values
        address from = address(this);
        uint256 beforeFromBalance = c.balanceOf(from);
        uint256 beforeToBalance = c.balanceOf(to);
        uint256 beforeTotal = c.totalSupply();

        // Execute transfer and catch revert
        bool reverted;
        try c.transfer(to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterFromBalance = c.balanceOf(from);
        uint256 afterToBalance = c.balanceOf(to);
        uint256 afterTotal = c.totalSupply();

        // If transfer succeeded (did not revert), then totalSupply must be unchanged
        // and balances of from+to must equal their previous sum (i.e., transfer is just movement between them).
        assert(reverted || (afterTotal == beforeTotal && afterFromBalance + afterToBalance == beforeFromBalance + beforeToBalance));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function taking inputs: caller (address) is implicitly this contract
    // We simulate owner vs non-owner by using the fact that the deployed c's owner is the deployer (the test deployer),
    // and subsequent calls from this contract will be non-owner unless this contract is the owner.
    // To allow both possibilities we first read the owner, then branch behavior by attempting freezeAccount
    // from this contract (which will revert if this contract is not owner) and also attempt a call that should
    // succeed only when msg.sender == owner by calling from the owner via c.freezeAccount (owner can only be the deployer,
    // but we cannot make arbitrary external calls as other addresses). Therefore the property asserts the relation
    // between who is owner and whether this contract's call reverts, and that a successful call sets frozenAccount.

    function run(address target, bool freeze) public payable {
        require(target != address(0));
        // read current owner and frozen status
        address owner = c.owner();
        bool before = c.frozenAccount(target);

        // Try calling freezeAccount from this contract and capture whether it reverted
        bool reverted;
        try c.freezeAccount(target, freeze) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the attempt, read frozen status again
        bool after = c.frozenAccount(target);

        // General rule to assert:
        // If this contract is the owner, the call must not revert and frozenAccount(target) must equal the requested value.
        // If this contract is not the owner, the call must revert and frozenAccount(target) must be unchanged.
        assert((address(this) == owner && reverted == false && after == freeze) ||
               (address(this) != owner && reverted == true && after == before));
    }

    receive() external payable {}
}

