contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: params choose an amount to burn and an address to act as caller
    // msg.sender for calls to c will be this contract, which is the original deployer/owner of c
    function run(uint256 burnAmount, address other) public payable {
        require(other != address(0));
        // Read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalanceThis = c.balanceOf(address(this));
        uint256 beforeBalanceOther = c.balanceOf(other);

        // attempt burn as owner (this contract is the owner because it deployed c)
        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalanceThis = c.balanceOf(address(this));
        uint256 afterBalanceOther = c.balanceOf(other);

        // Rule: If burn succeeded then totalSupply and caller balance decreased by burnAmount,
        // and other balances unchanged. If burn reverted then none of these three observables changed.
        assert(
            (!reverted && afterTotal + burnAmount == beforeTotal && afterBalanceThis + burnAmount == beforeBalanceThis && afterBalanceOther == beforeBalanceOther)
            || (reverted && afterTotal == beforeTotal && afterBalanceThis == beforeBalanceThis && afterBalanceOther == beforeBalanceOther)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint256 mintedAmount) public payable {
        require(target != address(0));
        // Read pre-state
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalTarget = c.balanceOf(target);

        // Try minting and capture whether it reverted
        bool reverted;
        try c.mintToken(target, mintedAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalTarget = c.balanceOf(target);

        // If call succeeded, totalSupply and target balance must have increased by mintedAmount.
        // If call reverted, both must be unchanged.
        assert((!reverted && afterTotal == beforeTotal + mintedAmount && afterBalTarget == beforeBalTarget + mintedAmount)
               || (reverted && afterTotal == beforeTotal && afterBalTarget == beforeBalTarget));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: caller will be msg.sender of calls from this contract, so we simulate by calling c methods directly.
    // We take a boolean callByOwner which when true we first ensure this contract is the owner by reading c.owner() and
    // if not, we try to make this contract the owner by relying on initial owner being the deployer (the checker deploys c fresh
    // with owner set to deployer, which is the test deployer, not this contract). To keep this general, we do NOT assume ownership.
    // Instead we observe owner before and after trying owned(), and check the general property: success implies owner changed to msg.sender,
    // failure implies owner unchanged.
    function run() public payable {
        // read owner before
        address ownerBefore = c.owner();
        bool reverted;
        // call owned() and catch revert
        try c.owned() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter = c.owner();
        // If call did not revert, ownerAfter must equal address(this). If it reverted, ownerAfter must equal ownerBefore.
        assert(reverted ? ownerAfter == ownerBefore : ownerAfter == address(this));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool callOwned) public payable {
        require(true);
        address ownerBefore = c.owner();
        bool reverted;
        // perform the call as a top-level statement; use callOwned to choose whether to attempt the call
        if (callOwned) {
            try c.owned() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // if we don't call, treat as not reverted and owner unchanged path
            reverted = true;
        }
        address ownerAfter = c.owner();
        // If the call did not revert then owner must have become this contract; if it reverted (or we didn't call) owner must be unchanged
        assert(reverted ? ownerAfter == ownerBefore : ownerAfter == address(this));
    }
    receive() external payable { }
}

