contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(bool doCall) public payable {
        require(true);
        address ownerBefore = c.owner();
        bool didCall;
        bool reverted;
        // Perform the potentially state-changing call as a single top-level statement.
        // We cannot put the call inside an if/try/other, so always perform it but
        // use a flag to decide whether to execute the call by calling a no-op when not desired.
        // To respect the requirement that state-changing calls be top-level, we use try/catch at top level.
        if (doCall) {
            didCall = true;
            try c.owned() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            didCall = false;
            // Do not call c.owned(); treat as if it reverted (no state change)
            reverted = true;
        }

        address ownerAfter = c.owner();
        // If we attempted the call and it did not revert, owner must become this contract;
        // if it reverted or we didn't call, owner must remain unchanged.
        assert((didCall && !reverted) ? ownerAfter == address(this) : ownerAfter == ownerBefore);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try a transfer and observe whether it reverts and public state
    function run(address to, uint256 value) public payable {
        require(true);
        // record sender (this contract) balance in c before
        uint256 beforeFrom = c.balanceOf(address(this));
        uint256 beforeTo = c.balanceOf(to);
        uint256 beforeTotal = c.totalSupply();

        bool reverted;
        // attempt transfer from this contract to `to` with value `value`
        try c.transfer(to, value) returns (bool ok) {
            reverted = false;
            // ok should be true when transfer succeeded per implementation
            // read after-values to include in final assert
        } catch {
            reverted = true;
        }

        uint256 afterFrom = c.balanceOf(address(this));
        uint256 afterTo = c.balanceOf(to);
        uint256 afterTotal = c.totalSupply();

        // General rule:
        // - If the call reverted, then nothing about balances/totalSupply is required here (implementation may revert for many reasons).
        // - If it did not revert, then destination must not be zero address, totalSupply unchanged, sender and receiver balances changed by exactly value.
        assert(reverted || (to != address(0) && afterTotal == beforeTotal && afterFrom + value == beforeFrom && afterTo == beforeTo + value));
    }

    receive() external payable { }
}
